ALTER TYPE "ComplaintReason" ADD VALUE 'INCORRECT_AMOUNT';
ALTER TYPE "CaseStatus" ADD VALUE 'AWAITING_CUSTOMER';
ALTER TABLE "Case" ADD COLUMN title text NOT NULL DEFAULT 'Legacy case', ADD COLUMN "requestedOutcome" text NOT NULL DEFAULT 'HELP', ADD COLUMN "desiredResolution" text NOT NULL DEFAULT '', ADD COLUMN "policySnapshot" jsonb NOT NULL DEFAULT '{}', ADD COLUMN "closedAt" timestamptz, ADD COLUMN "closureReason" text;
CREATE INDEX case_inbox ON "Case"("merchantId",status,"createdAt",id);
ALTER TABLE "Merchant" ADD COLUMN "activePolicyVersionId" uuid;
ALTER TABLE "Merchant" ADD CONSTRAINT active_policy_tenant FOREIGN KEY(id,"activePolicyVersionId") REFERENCES "PolicyVersion"("merchantId",id);
ALTER TABLE "Evidence" ADD COLUMN "declaredType" text NOT NULL DEFAULT 'application/octet-stream', ADD COLUMN "uploadState" text NOT NULL DEFAULT 'RESERVED' CHECK("uploadState" IN ('RESERVED','UPLOADING','UPLOADED','QUEUED','PROCESSING','AVAILABLE','REJECTED','EXPIRED','FAILED')), ADD COLUMN "expiresAt" timestamptz NOT NULL DEFAULT now()+interval '5 minutes', ADD COLUMN "actualSize" bigint, ADD COLUMN "actualHash" text, ADD COLUMN "cleanObjectKey" text, ADD COLUMN "scannerVersion" text, ADD COLUMN "scannedAt" timestamptz, ADD COLUMN "failureCode" text, ADD COLUMN "leaseOwner" uuid, ADD COLUMN "leaseUntil" timestamptz, ADD COLUMN "nextAttemptAt" timestamptz DEFAULT now(), ADD COLUMN attempts integer NOT NULL DEFAULT 0;
CREATE TABLE "CaseComment"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"merchantId" uuid NOT NULL,"caseId" uuid NOT NULL,"authorId" uuid NOT NULL REFERENCES "User"(id),visibility text NOT NULL CHECK(visibility IN ('CUSTOMER','INTERNAL')),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),"createdAt" timestamptz NOT NULL DEFAULT now(),FOREIGN KEY("merchantId","caseId") REFERENCES "Case"("merchantId",id));
CREATE TABLE "CaseTimelineEvent"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"merchantId" uuid NOT NULL,"caseId" uuid NOT NULL,"actorId" uuid REFERENCES "User"(id),action text NOT NULL,"previousStatus" text,"newStatus" text,visibility text NOT NULL CHECK(visibility IN ('CUSTOMER','INTERNAL')),metadata jsonb NOT NULL DEFAULT '{}',"createdAt" timestamptz NOT NULL DEFAULT now(),FOREIGN KEY("merchantId","caseId") REFERENCES "Case"("merchantId",id));
CREATE TABLE "PolicyDraft"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),"merchantId" uuid NOT NULL REFERENCES "Merchant"(id),document jsonb NOT NULL,version integer NOT NULL DEFAULT 0,"publishedVersionId" uuid,"createdAt" timestamptz NOT NULL DEFAULT now(),FOREIGN KEY("merchantId","publishedVersionId") REFERENCES "PolicyVersion"("merchantId",id));
CREATE TABLE "EvidenceWorkerTenant"("merchantId" uuid NOT NULL REFERENCES "Merchant"(id),"roleName" text NOT NULL,PRIMARY KEY("merchantId","roleName"));
CREATE FUNCTION case_member(m uuid) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT EXISTS(SELECT 1 FROM "Membership" WHERE "merchantId"=m AND "userId"=NULLIF(current_setting('app.user_id',true),'')::uuid AND active)$$;
CREATE FUNCTION case_owner(m uuid) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT EXISTS(SELECT 1 FROM "Membership" WHERE "merchantId"=m AND "userId"=NULLIF(current_setting('app.user_id',true),'')::uuid AND active AND role='OWNER')$$;
CREATE FUNCTION case_visible(m uuid,c uuid) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT EXISTS(SELECT 1 FROM "Case" WHERE "merchantId"=m AND id=c)$$;
GRANT SELECT,INSERT,UPDATE ON "Case","Evidence","PolicyDraft" TO resolve_runtime,resolve_test;
GRANT SELECT,INSERT ON "CaseComment","CaseTimelineEvent","PolicyVersion","PolicyClause" TO resolve_runtime,resolve_test;
GRANT UPDATE("publishedAt") ON "PolicyVersion" TO resolve_runtime,resolve_test;
GRANT UPDATE("activePolicyVersionId") ON "Merchant" TO resolve_runtime,resolve_test;
CREATE POLICY case_customer_insert ON "Case" FOR INSERT TO resolve_runtime,resolve_test WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "openedBy"=NULLIF(current_setting('app.user_id',true),'')::uuid AND EXISTS(SELECT 1 FROM "CustomerOrder" co WHERE co."merchantId"="Case"."merchantId" AND co."orderId"="Case"."orderId" AND co."userId"="Case"."openedBy"));
CREATE POLICY case_customer_update ON "Case" FOR UPDATE TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "openedBy"=NULLIF(current_setting('app.user_id',true),'')::uuid) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "openedBy"=NULLIF(current_setting('app.user_id',true),'')::uuid);
CREATE POLICY evidence_write ON "Evidence" TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_visible("merchantId","caseId")) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_visible("merchantId","caseId") AND (case_member("merchantId") OR "uploaderUserId"=NULLIF(current_setting('app.user_id',true),'')::uuid));
CREATE POLICY owner_policy_insert ON "PolicyVersion" FOR INSERT TO resolve_runtime,resolve_test WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner("merchantId"));
CREATE POLICY owner_policy_publish ON "PolicyVersion" FOR UPDATE TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner("merchantId"));
CREATE POLICY owner_clause_insert ON "PolicyClause" FOR INSERT TO resolve_runtime,resolve_test WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner("merchantId"));
CREATE POLICY owner_merchant_policy ON "Merchant" FOR UPDATE TO resolve_runtime,resolve_test USING(id=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner(id));
DO $$DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['CaseComment','CaseTimelineEvent','PolicyDraft','EvidenceWorkerTenant'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY migration_access ON %I TO resolve_migrator USING(true) WITH CHECK(true)',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['CaseComment','CaseTimelineEvent'] LOOP
 EXECUTE format('CREATE POLICY visible ON %I FOR SELECT TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting(''app.merchant_id'',true),'''')::uuid AND case_visible("merchantId","caseId") AND (visibility=''CUSTOMER'' OR case_member("merchantId")))',t);
 EXECUTE format('CREATE POLICY append ON %I FOR INSERT TO resolve_runtime,resolve_test WITH CHECK("merchantId"=NULLIF(current_setting(''app.merchant_id'',true),'''')::uuid AND case_visible("merchantId","caseId") AND (visibility=''CUSTOMER'' OR case_member("merchantId")))',t);
 EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_mutation()',t);
 END LOOP;
END$$;
CREATE POLICY draft_owner ON "PolicyDraft" TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner("merchantId")) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND case_owner("merchantId"));
CREATE POLICY customer_case_audit ON "AuditEvent" FOR INSERT TO resolve_runtime,resolve_test WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "actorId"=NULLIF(current_setting('app.user_id',true),'')::uuid AND "aggregateType"='Case' AND case_visible("merchantId","aggregateId"));
CREATE POLICY customer_case_outbox ON "OutboxEvent" TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "eventType"='evidence.validate' AND EXISTS(SELECT 1 FROM "Evidence" e WHERE e.id="OutboxEvent"."aggregateId")) WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "eventType"='evidence.validate' AND EXISTS(SELECT 1 FROM "Evidence" e WHERE e.id="OutboxEvent"."aggregateId"));
CREATE POLICY case_idempotency ON "IdempotencyRecord" TO resolve_runtime,resolve_test USING("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "actorId"=NULLIF(current_setting('app.user_id',true),'')::uuid AND "routeScope" LIKE 'cases:%') WITH CHECK("merchantId"=NULLIF(current_setting('app.merchant_id',true),'')::uuid AND "actorId"=NULLIF(current_setting('app.user_id',true),'')::uuid AND "routeScope" LIKE 'cases:%');